describe('Network Request Timeout Retry Functionality', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should display retry button when network request times out', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(10000);
      });
    }).as('timedOutRequest');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@timedOutRequest', { timeout: 5000 }).then(() => {
      cy.get('[data-testid="timeout-error-message"]').should('be.visible');
      cy.get('[data-testid="retry-button"]').should('be.visible');
      cy.get('[data-testid="retry-button"]').should('contain', 'Retry');
    });
  });

  it('should successfully retry and fetch data after timeout', () => {
    let requestCount = 0;

    cy.intercept('GET', '/api/data', (req) => {
      requestCount++;
      if (requestCount === 1) {
        req.reply((res) => {
          res.delay(10000);
        });
      } else {
        req.reply({
          statusCode: 200,
          body: { data: 'Success after retry', id: 123 },
        });
      }
    }).as('dataRequest');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.wait('@dataRequest', { timeout: 5000 }).then(() => {
      cy.get('[data-testid="timeout-error-message"]').should('be.visible');
      cy.get('[data-testid="retry-button"]').click();
      cy.wait('@dataRequest');
      cy.get('[data-testid="success-message"]').should('be.visible');
      cy.get('[data-testid="data-display"]').should('contain', 'Success after retry');
      cy.get('[data-testid="timeout-error-message"]').should('not.exist');
    });
  });

  it('should disable retry button while request is in progress', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(3000);
      });
    }).as('delayedRequest');

    cy.get('[data-testid="fetch-data-button"]').click();
    cy.get('[data-testid="retry-button"]').should('be.disabled');
    cy.wait('@delayedRequest');
    cy.get('[data-testid="retry-button"]').should('not.be.disabled');
  });

  it('should show error after maximum retry attempts exceeded', () => {
    let requestCount = 0;

    cy.intercept('GET', '/api/data', (req) => {
      requestCount++;
      req.reply((res) => {
        res.delay(10000);
      });
    }).as('failingRequest');

    cy.get('[data-testid="fetch-data-button"]').click();

    for (let i = 0; i < 3; i++) {
      cy.wait('@failingRequest', { timeout: 5000 }).then(() => {
        cy.get('[data-testid="retry-button"]').should('be.visible');
        if (i < 2) {
          cy.get('[data-testid="retry-button"]').click();
        }
      });
    }

    cy.get('[data-testid="max-retries-error"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').should('not.exist');
  });
});
